SET XACT_ABORT ON;
BEGIN TRANSACTION;
CREATE TABLE dbo.Stores(Id int IDENTITY PRIMARY KEY,Name nvarchar(160) NOT NULL,Code nvarchar(32) NOT NULL UNIQUE,IsActive bit NOT NULL DEFAULT 1,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Users(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,Username nvarchar(80) NOT NULL,DisplayName nvarchar(160) NOT NULL,PasswordHash nvarchar(500) NOT NULL,Role nvarchar(32) NOT NULL DEFAULT 'Staff',IsActive bit NOT NULL DEFAULT 1,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_Users_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT UQ_Users_Store_Username UNIQUE(StoreId,Username));
CREATE TABLE dbo.DiningTables(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,Name nvarchar(40) NOT NULL,Capacity int NOT NULL DEFAULT 2,Status nvarchar(24) NOT NULL DEFAULT 'Available',IsActive bit NOT NULL DEFAULT 1,CONSTRAINT FK_DiningTables_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT UQ_DiningTables_Store_Name UNIQUE(StoreId,Name),CONSTRAINT CK_DiningTables_Capacity CHECK(Capacity>0),CONSTRAINT CK_DiningTables_Status CHECK(Status IN('Available','Occupied','Reserved')));
CREATE TABLE dbo.ItemCategories(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,Name nvarchar(100) NOT NULL,CONSTRAINT FK_ItemCategories_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT UQ_ItemCategories_Store_Name UNIQUE(StoreId,Name));
CREATE TABLE dbo.SaleItems(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,CategoryId int NULL,Code nvarchar(40) NOT NULL,Name nvarchar(160) NOT NULL,Price decimal(18,2) NOT NULL,IsActive bit NOT NULL DEFAULT 1,UpdatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_SaleItems_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT FK_SaleItems_Categories FOREIGN KEY(CategoryId) REFERENCES dbo.ItemCategories(Id),CONSTRAINT UQ_SaleItems_Store_Code UNIQUE(StoreId,Code),CONSTRAINT CK_SaleItems_Price CHECK(Price>=0));
CREATE TABLE dbo.Customers(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,Name nvarchar(160) NOT NULL,Phone nvarchar(40) NULL,Address nvarchar(300) NULL,CONSTRAINT FK_Customers_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id));
CREATE TABLE dbo.SalesOrders(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,TableId int NULL,CustomerId int NULL,OrderNumber nvarchar(40) NOT NULL,Channel nvarchar(20) NOT NULL,Status nvarchar(24) NOT NULL,Subtotal decimal(18,2) NOT NULL,DiscountAmount decimal(18,2) NOT NULL DEFAULT 0,Total decimal(18,2) NOT NULL,Notes nvarchar(1000) NULL,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),ClosedAtUtc datetime2(3) NULL,CONSTRAINT FK_SalesOrders_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT FK_SalesOrders_Tables FOREIGN KEY(TableId) REFERENCES dbo.DiningTables(Id),CONSTRAINT FK_SalesOrders_Customers FOREIGN KEY(CustomerId) REFERENCES dbo.Customers(Id),CONSTRAINT UQ_SalesOrders_Store_Number UNIQUE(StoreId,OrderNumber),CONSTRAINT CK_SalesOrders_Channel CHECK(Channel IN('Table','TakeAway','Delivery')),CONSTRAINT CK_SalesOrders_Amounts CHECK(Subtotal>=0 AND DiscountAmount>=0 AND Total>=0));
CREATE TABLE dbo.SalesOrderLines(Id int IDENTITY PRIMARY KEY,SalesOrderId int NOT NULL,SaleItemId int NOT NULL,ItemNameSnapshot nvarchar(160) NOT NULL,UnitPrice decimal(18,2) NOT NULL,Quantity decimal(18,3) NOT NULL,LineTotal decimal(18,2) NOT NULL,CONSTRAINT FK_SalesOrderLines_Orders FOREIGN KEY(SalesOrderId) REFERENCES dbo.SalesOrders(Id) ON DELETE CASCADE,CONSTRAINT FK_SalesOrderLines_Items FOREIGN KEY(SaleItemId) REFERENCES dbo.SaleItems(Id),CONSTRAINT CK_SalesOrderLines_Quantity CHECK(Quantity>0));
CREATE TABLE dbo.StockItems(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,Code nvarchar(40) NOT NULL,Name nvarchar(160) NOT NULL,Category nvarchar(100) NOT NULL,Unit nvarchar(20) NOT NULL,Quantity decimal(18,3) NOT NULL DEFAULT 0,MinimumQuantity decimal(18,3) NOT NULL DEFAULT 0,UnitCost decimal(18,4) NOT NULL DEFAULT 0,IsActive bit NOT NULL DEFAULT 1,CONSTRAINT FK_StockItems_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT UQ_StockItems_Store_Code UNIQUE(StoreId,Code),CONSTRAINT CK_StockItems_Quantities CHECK(Quantity>=0 AND MinimumQuantity>=0 AND UnitCost>=0));
CREATE TABLE dbo.StockMovements(Id bigint IDENTITY PRIMARY KEY,StoreId int NOT NULL,StockItemId int NOT NULL,SupplierId int NULL,QuantityDelta decimal(18,3) NOT NULL,MovementType nvarchar(24) NOT NULL,Reference nvarchar(80) NULL,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_StockMovements_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT FK_StockMovements_StockItems FOREIGN KEY(StockItemId) REFERENCES dbo.StockItems(Id),CONSTRAINT FK_StockMovements_Suppliers FOREIGN KEY(SupplierId) REFERENCES dbo.Suppliers(Id));
CREATE TABLE dbo.Recipes(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,SaleItemId int NOT NULL,SalePriceSnapshot decimal(18,2) NOT NULL,IsActive bit NOT NULL DEFAULT 1,CONSTRAINT FK_Recipes_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT FK_Recipes_SaleItems FOREIGN KEY(SaleItemId) REFERENCES dbo.SaleItems(Id),CONSTRAINT UQ_Recipes_Store_SaleItem UNIQUE(StoreId,SaleItemId));
CREATE TABLE dbo.RecipeIngredients(Id int IDENTITY PRIMARY KEY,RecipeId int NOT NULL,StockItemId int NOT NULL,Quantity decimal(18,3) NOT NULL,CONSTRAINT FK_RecipeIngredients_Recipes FOREIGN KEY(RecipeId) REFERENCES dbo.Recipes(Id) ON DELETE CASCADE,CONSTRAINT FK_RecipeIngredients_StockItems FOREIGN KEY(StockItemId) REFERENCES dbo.StockItems(Id),CONSTRAINT UQ_RecipeIngredients_Recipe_Stock UNIQUE(RecipeId,StockItemId),CONSTRAINT CK_RecipeIngredients_Quantity CHECK(Quantity>0));
CREATE TABLE dbo.Suppliers(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,Name nvarchar(160) NOT NULL,ContactName nvarchar(160) NULL,Phone nvarchar(40) NULL,Email nvarchar(160) NULL,Address nvarchar(300) NULL,TaxNumber nvarchar(32) NULL,Notes nvarchar(500) NULL,IsActive bit NOT NULL DEFAULT 1,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_Suppliers_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id));
CREATE UNIQUE INDEX UX_Suppliers_Store_Name ON dbo.Suppliers(StoreId,Name) WHERE IsActive=1;
CREATE TABLE dbo.TableReservations(Id int IDENTITY PRIMARY KEY,StoreId int NOT NULL,TableId int NULL,CustomerId int NULL,GuestName nvarchar(160) NOT NULL,Phone nvarchar(40) NULL,GuestCount int NOT NULL,StartsAtLocal datetime2(0) NOT NULL,DurationMinutes int NOT NULL DEFAULT 120,Status nvarchar(20) NOT NULL DEFAULT 'Booked',Notes nvarchar(500) NULL,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_TableReservations_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT FK_TableReservations_Tables FOREIGN KEY(TableId) REFERENCES dbo.DiningTables(Id),CONSTRAINT FK_TableReservations_Customers FOREIGN KEY(CustomerId) REFERENCES dbo.Customers(Id),CONSTRAINT CK_TableReservations_GuestCount CHECK(GuestCount BETWEEN 1 AND 50),CONSTRAINT CK_TableReservations_Duration CHECK(DurationMinutes BETWEEN 30 AND 360),CONSTRAINT CK_TableReservations_Status CHECK(Status IN('Booked','Seated','Cancelled','NoShow')));
CREATE INDEX IX_TableReservations_Store_Start_Status ON dbo.TableReservations(StoreId,StartsAtLocal,Status);
CREATE TABLE dbo.OrderPayments(Id bigint IDENTITY PRIMARY KEY,StoreId int NOT NULL,SalesOrderId int NOT NULL,Amount decimal(18,2) NOT NULL,Method nvarchar(24) NOT NULL,Reference nvarchar(160) NULL,PaidAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_OrderPayments_Stores FOREIGN KEY(StoreId) REFERENCES dbo.Stores(Id),CONSTRAINT FK_OrderPayments_SalesOrders FOREIGN KEY(SalesOrderId) REFERENCES dbo.SalesOrders(Id) ON DELETE CASCADE,CONSTRAINT CK_OrderPayments_Amount CHECK(Amount>0),CONSTRAINT CK_OrderPayments_Method CHECK(Method IN(N'Cash',N'Card',N'BankTransfer',N'Other')));
CREATE INDEX IX_OrderPayments_Store_Order_PaidAt ON dbo.OrderPayments(StoreId,SalesOrderId,PaidAtUtc);
CREATE INDEX IX_SalesOrders_Store_Status_Created ON dbo.SalesOrders(StoreId,Status,CreatedAtUtc DESC);
CREATE INDEX IX_StockMovements_Store_Item_Created ON dbo.StockMovements(StoreId,StockItemId,CreatedAtUtc DESC);
CREATE INDEX IX_SalesOrderLines_SaleItem ON dbo.SalesOrderLines(SaleItemId);
COMMIT TRANSACTION;
